parameters.jsCode:
// Fusionner les résultats de toutes les branches
const stepData = $('Récupérer étapes dues (DB)').item.json;
let message = '';

const fu1 = $('Claude – Relance J+3').all(false);
const fu2 = $('Claude – Relance J+7 (finale)').all(false);

if (fu1.length > 0) {
  message = fu1[0].json.content[0].text.trim();
} else if (fu2.length > 0) {
  message = fu2[0].json.content[0].text.trim();
}

const delay = Math.floor(Math.random() * 60000) + 45000;

return [{
  json: {
    ...stepData,
    message,
    actionDelay: delay,
    dryRun: $vars.DRY_RUN === 'true',
  }
}];
